});

test('invoiceTotals calculates VAT on discounted amounts', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  }).value;

  const totals = invoiceTotals(invoice);

  const lineAmount = 10 * 9500;
  const discount = (lineAmount * 10) / 100;
  const amountAfterDiscount = lineAmount - discount;
  const expectedVAT = Math.round((amountAfterDiscount * 21) / 100);

  assert.equal(totals.subtotal, lineAmount);
  assert.equal(totals.discount, Math.round(discount));
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, lineAmount - Math.round(discount) + expectedVAT);
});

