test('createInvoice uses tier discount in calculations', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const totals = invoiceTotals(invoice);
  const expected = 10 * 9500;
  const tierDiscount = (expected * 5) / 100;

  assert.equal(totals.subtotal, expected);
  assert.equal(totals.discount, Math.round(tierDiscount));
  assert.equal(totals.total, expected - Math.round(tierDiscount));
});

test('lineVAT calculates VAT on amount after discount', () => {
  const line = {
    qty: 10,
    unitPrice: 1000,
    discountPercent: 10,
    vatRate: 21,
  };

  const vat = lineVAT(line);
  const lineAmount = 10 * 1000;
  const afterDiscount = lineAmount - (lineAmount * 10) / 100;
  const expectedVAT = Math.round((afterDiscount * 21) / 100);

  assert.equal(vat, expectedVAT);
});

test('lineVAT handles 0% VAT rate', () => {
