test('invoiceTotals returns correct subtotal, discount, vat, and total', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10 },
      { sku: 'LOGO-PACK', qty: 1 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);
  const subtotal = 95000 + 120000;
