test('createInvoice uses tier discount in calculations', () => {
  const invoice = createInvoice({
    customerId: 'C-001',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10 }],
  }).value;

  const totals = invoiceTotals(invoice);
  const subtotal = 10 * 9500;
  const tierDiscount = Math.round((subtotal * 5) / 100);
  const afterDiscount = subtotal - tierDiscount;
  const vat = Math.round((afterDiscount * 21) / 100);

  assert.equal(totals.subtotal, subtotal);
  assert.equal(totals.discount, tierDiscount);
  assert.equal(totals.vat, vat);
  assert.equal(totals.total, subtotal - tierDiscount + vat);
});

test('lineVAT calculates VAT on amount after discount', () => {
  const line = {
    qty: 10,
    unitPrice: 1000,
    discountPercent: 10,
    vatRate: 21,
  };

  const vat = lineVAT(line);
  const lineAmount = 10 * 1000;
  const afterDiscount = lineAmount - (lineAmount * 10) / 100;
  const expectedVAT = Math.round((afterDiscount * 21) / 100);

  assert.equal(vat, expectedVAT);
});

test('lineVAT handles 0% VAT rate', () => {
