    discountPercent: 0,
    vatRate: 9,
  };

  const vat = lineVAT(line);
  const lineAmount = 100 * 249;
  const expectedVAT = Math.round((lineAmount * 9) / 100);

  assert.equal(vat, expectedVAT);
});

test('lineVAT clamps to 0 (never negative)', () => {
  const line = {
    qty: 10,
    unitPrice: 1000,
    discountPercent: 150,
    vatRate: 21,
  };

  const vat = lineVAT(line);
  assert.ok(vat >= 0);
});

test('invoiceTotals includes vat in calculation', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 10, discountPercent: 0 },
      { sku: 'PRINT-A4', qty: 100, discountPercent: 0 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);

  const devTotal = 10 * 9500;
  const devVAT = Math.round((devTotal * 21) / 100);
  const printTotal = 100 * 37;
  const printVAT = Math.round((printTotal * 9) / 100);

  assert.equal(totals.subtotal, devTotal + printTotal);
  assert.equal(totals.discount, 0);
  assert.equal(totals.vat, devVAT + printVAT);
  assert.equal(totals.total, totals.subtotal + totals.vat);
});

test('invoiceTotals calculates VAT on discounted amounts', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [{ sku: 'DEV-HOUR', qty: 10, discountPercent: 10 }],
  }).value;

  const totals = invoiceTotals(invoice);

  const lineAmount = 10 * 9500;
  const discount = (lineAmount * 10) / 100;
  const amountAfterDiscount = lineAmount - discount;
  const expectedVAT = Math.round((amountAfterDiscount * 21) / 100);

  assert.equal(totals.subtotal, lineAmount);
  assert.equal(totals.discount, Math.round(discount));
  assert.equal(totals.vat, expectedVAT);
  assert.equal(totals.total, lineAmount - Math.round(discount) + expectedVAT);
});

test('invoiceTotals with mixed VAT rates', () => {
  const invoice = createInvoice({
    customerId: 'C-002',
    issueDate: '2024-02-15',
    lines: [
      { sku: 'DEV-HOUR', qty: 5 },
      { sku: 'PRINT-A4', qty: 50 },
      { sku: 'WORKSHOP-DAY', qty: 1 },
    ],
  }).value;

  const totals = invoiceTotals(invoice);

  const devAmount = 5 * 9500;
  const devVAT = Math.round((devAmount * 21) / 100);
  const printAmount = 50 * 37;
  const printVAT = Math.round((printAmount * 9) / 100);
  const workshopAmount = 1 * 60000;
  const workshopVAT = 0;

  assert.equal(totals.vat, devVAT + printVAT + workshopVAT);
  assert.equal(
    totals.total,
    devAmount + printAmount + workshopAmount + devVAT + printVAT + workshopVAT
  );
});

